window.HVAC_DATA={"faultCodes":[],"trees":[{"id":"generic-boiler-lockout","title":"Boiler lockout","equipment":"Hydronic boilers and systems","generic":true,"start":"n1","nodes":{"n1":{"type":"question","text":"Can you read a fault or lockout code from the boiler display or control?","options":[{"label":"Yes, I have a code","next":"r_code"},{"label":"No code available","next":"n2"}]},"r_code":{"type":"result","cause":"A fault code identifies the safety or condition that locked out the boiler.","fix":["Record the code and time before resetting.","Look it up in the Fault codes tab, then confirm in the manufacturer manual (Manuals tab).","Follow the manufacturer's reset procedure. Repeated lockouts mean the cause must be found, not reset away."]},"n2":{"type":"question","text":"Which safety circuit opened? (Check status indicators per the boiler manual.)","options":[{"label":"Flame or ignition failure","next":"r_ign"},{"label":"Low water or no flow","next":"r_water"},{"label":"High limit or high temperature","next":"r_limit"},{"label":"Air pressure, flue or condensate switch","next":"r_air"},{"label":"Cannot tell","next":"r_unknown"}]},"r_ign":{"type":"result","cause":"Ignition or flame failure.","fix":["Check gas supply and shutoffs, igniter and flame sensor per the manufacturer's procedure.","Check vent and combustion air.","Gas work follows the manufacturer's procedure and local code."]},"r_water":{"type":"result","cause":"Low water or no flow.","fix":["Check system pressure, water level or low-water cut-off, and look for leaks.","Check pump operation and flow switch.","Do not bypass the low-water cut-off or flow switch.","If the boiler is hot and low on water, let it cool before adding water."]},"r_limit":{"type":"result","cause":"High limit or high temperature.","fix":["Allow the boiler to cool before resetting.","Check flow, supply sensor accuracy and setpoints.","Do not raise or bypass the limit."]},"r_air":{"type":"result","cause":"Air pressure, flue or condensate switch is open.","fix":["Check vent and intake for blockage, the condensate drain and trap, and the switch tubing per the manual.","Do not jumper the switch."]},"r_unknown":{"type":"result","cause":"The tripped safety cannot be identified from outside.","fix":["Check the boiler manual's status indicator or diagnostics section (Manuals tab: search lockout).","Check the control for stored fault history.","Contact the manufacturer support line if the cause is still unclear."]}}},{"id":"generic-no-heat","title":"No heat","equipment":"Hydronic boilers and systems","generic":true,"start":"n1","nodes":{"n1":{"type":"question","text":"Is the thermostat or controller calling for heat (call-for-heat present at the boiler or its control)?","options":[{"label":"Yes, call is present","next":"n2"},{"label":"No call","next":"r_nocall"}]},"r_nocall":{"type":"result","cause":"No call for heat is reaching the boiler.","fix":["Check the thermostat or zone controller setpoint, mode and batteries.","Check zone valve or zone relay operation and 24 V control power.","Check for a tripped breaker, blown control fuse or an open limit or switch in the call-for-heat circuit.","Do not jumper any limit, switch or safety device to force a call for heat."]},"n2":{"type":"question","text":"Does the boiler start its sequence (fan, igniter or burner start)?","options":[{"label":"Yes","next":"n3"},{"label":"No","next":"n4"}]},"n4":{"type":"question","text":"Does the boiler display a lockout, fault or error code?","options":[{"label":"Yes","next":"r_code"},{"label":"No","next":"r_nostart"}]},"r_code":{"type":"result","cause":"The boiler is in a fault or lockout state.","fix":["Record the code before resetting anything.","Look it up in the Fault codes tab or the manufacturer manual (Manuals tab).","Follow the manufacturer's reset and troubleshooting procedure. Do not bypass safety devices."]},"r_nostart":{"type":"result","cause":"The start sequence is not beginning even though a call is present.","fix":["Verify power to the boiler and that the service switch is on.","Check the safety string status per the boiler manual: low-water cut-off, limits, flow switch, gas pressure or air pressure switches.","Check that an outdoor-reset or warm-weather shutdown setting is not blocking the call (see the control's manual).","Do not jumper any safety device."]},"n3":{"type":"question","text":"Does the burner light and stay lit?","options":[{"label":"Yes","next":"n5"},{"label":"No","next":"r_flame"}]},"r_flame":{"type":"result","cause":"Ignition or flame problem.","fix":["Check the gas supply and shutoff valves.","Check the flame sensor and igniter using the manufacturer's procedure.","Check vent and condensate drain for blockage per the manual.","Gas work must follow the manufacturer's procedure and local code."]},"n5":{"type":"question","text":"Is the boiler supply temperature rising toward setpoint?","options":[{"label":"Yes","next":"n6"},{"label":"No","next":"r_nohi"}]},"r_nohi":{"type":"result","cause":"The boiler is firing but not producing heat.","fix":["Check firing rate and gas pressure against the manual.","Check for a fouled or dirty heat exchanger.","Compare the boiler sensor reading with a calibrated thermometer."]},"n6":{"type":"question","text":"Is the system pump running, with flow through the zone (pipe warming, flow indicated)?","options":[{"label":"Yes","next":"n7"},{"label":"No","next":"r_pump"}]},"r_pump":{"type":"result","cause":"Heat is produced but not delivered.","fix":["Check pump power and the relay or controller output that runs it (see the Pump not running tree).","Check that the zone valve actuator or end switch is opening.","Check for an air lock, a closed isolation valve or a clogged strainer."]},"n7":{"type":"question","text":"Is the supply-to-return delta-T far below the design delta-T?","options":[{"label":"Yes, much lower","next":"r_lowdt"},{"label":"No, about normal","next":"r_load"}]},"r_lowdt":{"type":"result","cause":"Heat is flowing but not transferring to the space.","fix":["Use the Readings tab delta-T calculator.","Check for excess flow, an open bypass, air in terminal units or failed zone valves.","Check terminal units (fan coils, baseboard) for fan or airflow problems."]},"r_load":{"type":"result","cause":"The plant looks normal; the load may exceed capacity, or setpoints are too low.","fix":["Check heating setpoints and the reset curve (Readings tab).","Check the building side: outside air dampers, air handler coils, envelope problems."]}}},{"id":"generic-poor-delta-t","title":"Poor delta-T","equipment":"Hydronic boilers and systems","generic":true,"start":"n1","nodes":{"n1":{"type":"question","text":"Is the measured delta-T lower or higher than the target? (Calculate it in the Readings tab.)","options":[{"label":"Lower than target","next":"n2"},{"label":"Higher than target","next":"n4"}]},"n2":{"type":"question","text":"Are there open bypasses, over-pumped circuits, or three-way valves stuck in bypass?","options":[{"label":"Yes","next":"r_exc"},{"label":"No","next":"n3"}]},"r_exc":{"type":"result","cause":"Excess flow or a bypass is reducing delta-T.","fix":["Check pump speed and balancing valve settings against the design flow.","Check three-way valve actuators and bypass lines.","Re-measure delta-T after correcting."]},"n3":{"type":"question","text":"Is the load very light (few terminal units calling, mild weather)?","options":[{"label":"Yes","next":"r_light"},{"label":"No","next":"r_ht"}]},"r_light":{"type":"result","cause":"Low delta-T from a light load.","fix":["Re-check delta-T when more zones are calling or at a colder outdoor temperature.","Check reset and setpoints for the current weather (Readings tab)."]},"r_ht":{"type":"result","cause":"Terminal units may not be transferring heat.","fix":["Check coils, fins and fans for fouling or failure.","Check control valves are actually opening.","Check for air binding in terminal units and bleed per the system procedure."]},"n4":{"type":"question","text":"Is the pump running at the expected speed, with all isolation and zone valves open?","options":[{"label":"Yes","next":"r_restrict"},{"label":"No or unsure","next":"r_valves"}]},"r_valves":{"type":"result","cause":"Flow is being reduced or blocked.","fix":["Check pump speed setting, motor and coupling.","Open or replace closed or failed isolation and zone valves.","Check the pump control output."]},"r_restrict":{"type":"result","cause":"Flow is restricted somewhere in the circuit.","fix":["Clean strainers and check differential pressure across them.","Check balancing valves, air elimination and check valves.","Check for a partly closed or failed valve and for fouled heat exchangers."]}}},{"id":"generic-pump-not-running","title":"Pump not running","equipment":"Hydronic boilers and systems","generic":true,"start":"n1","nodes":{"n1":{"type":"question","text":"Is there power at the pump terminals when it should be running?","options":[{"label":"No power at the pump","next":"n2"},{"label":"Power is present","next":"n3"}]},"n2":{"type":"question","text":"Is the controller or relay calling for the pump (pump output energized)?","options":[{"label":"Yes, output is energized","next":"r_wiring"},{"label":"No, no call","next":"r_nocallp"}]},"r_wiring":{"type":"result","cause":"The call is present but power is not reaching the pump.","fix":["De-energize and lock out before inspecting wiring.","Check relay contacts, fuses, breaker, disconnect and wiring.","Re-test with a meter once safely re-energized per your site procedure.","Electrical checks must follow site lockout/tagout and the equipment manufacturer's procedure."]},"r_nocallp":{"type":"result","cause":"The control is not calling the pump.","fix":["Check control settings such as pump exercise, warm-weather shutdown and pump delay (see the manufacturer manual in the Manuals tab).","Check thermostat and zone calls.","Check the control for fault codes (Fault codes tab)."]},"n3":{"type":"question","text":"Is the pump motor shaft or fan turning?","options":[{"label":"Not turning","next":"r_seize"},{"label":"Turning","next":"r_noflow"}]},"r_seize":{"type":"result","cause":"The motor is energized but not turning.","fix":["De-energize and lock out first.","Check for a seized rotor or bearings, foreign material, and a failed capacitor where applicable, using the pump manufacturer's procedure.","Replace or repair per the pump manual.","Electrical checks must follow site lockout/tagout and the equipment manufacturer's procedure, including discharging capacitors where applicable."]},"r_noflow":{"type":"result","cause":"The pump is turning but there is no flow.","fix":["Check the coupling, if the pump is coupled.","Check for an air lock and bleed the pump per the system procedure.","Check for closed valves, a damaged impeller, and rotation direction on three-phase pumps."]}}},{"id":"generic-short-cycling","title":"Short cycling","equipment":"Hydronic boilers and systems","generic":true,"start":"n1","nodes":{"n1":{"type":"question","text":"Does the boiler shut off on a high-limit or high supply temperature, rather than when the setpoint is satisfied?","options":[{"label":"Yes, high limit or high temperature","next":"n2"},{"label":"No","next":"n3"}]},"n2":{"type":"question","text":"Is there good flow while the boiler runs (pump running, valves open, strainer clean)?","options":[{"label":"Yes, flow is good","next":"n2b"},{"label":"No or unsure","next":"r_flow"}]},"r_flow":{"type":"result","cause":"Insufficient flow is overheating the boiler.","fix":["Check the pump, isolation and zone valves, strainer and air.","Confirm the boiler's minimum flow requirement in its manual.","Do not raise or bypass the high limit."]},"n2b":{"type":"question","text":"Is the supply setpoint or reset curve higher than the building load needs?","options":[{"label":"Yes","next":"r_setpt"},{"label":"No","next":"r_sensor"}]},"r_setpt":{"type":"result","cause":"The setpoint is too high for the load, so the boiler reaches it quickly and shuts off.","fix":["Lower the setpoint or reset curve (Readings tab for a check).","Review differential and minimum-on-time settings in the control manual.","Consider the manufacturer's guidance on minimum load or buffer volume."]},"r_sensor":{"type":"result","cause":"Possible sensor or control problem.","fix":["Check supply sensor accuracy against a calibrated thermometer and check its wiring.","Review control differential and anti-cycle settings per the manual.","Record any codes and look them up in the Fault codes tab."]},"n3":{"type":"question","text":"Does it shut off because the call for heat ends (zone or thermostat satisfied quickly)?","options":[{"label":"Yes, the call ends","next":"n4"},{"label":"No, it stops with the call still present","next":"r_interlock"}]},"n4":{"type":"question","text":"Is the heating load small compared with the boiler's minimum output (few zones calling)?","options":[{"label":"Yes","next":"r_oversize"},{"label":"No","next":"r_tstat"}]},"r_oversize":{"type":"result","cause":"Boiler minimum output exceeds the load for the zones currently calling.","fix":["Check modulation and minimum-fire settings per the manual.","Consider buffer volume or zoning changes as recommended by the manufacturer."]},"r_tstat":{"type":"result","cause":"Thermostat or zone control cycling.","fix":["Check thermostat cycle-rate and anticipator settings and its location.","Check for zone valve end-switch chatter.","Check for a thermostat or sensor drifting or reading a draft."]},"r_interlock":{"type":"result","cause":"Cycling is caused by a safety or sensor interlock opening.","fix":["Check flame signal, air or flue pressure switch, flow switch and low-water cut-off status per the manual.","Record any codes and look them up in the Fault codes tab.","Do not bypass any safety interlock."]}}}],"pt":[],"manifest":[]};
